    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initialize the pool so it's not in the initial zero state
        c.initialize(address(0), address(1), 1000 ether, 100 ether, 100, 100, bytes32(0), false, false);
        uint16 originalFeeRate = c.feeRate();

        // Use a non-owner to attempt changing feeRate
        address nonOwner = address(0x1234);
        vm.prank(nonOwner);
        // In the reference, setFeeRate reverts for non-owner; in the buggy version, it succeeds
        // We wrap in try/catch to capture the revert boolean
        bool ok;
        try c.setFeeRate(500) { ok = true; } catch { ok = false; }

        // If the call succeeded (buggy), feeRate changed; if reverted (reference), feeRate unchanged
        // The test assertion should pass on reference (feeRate unchanged, ok=false) and fail on bug (feeRate changed, ok=true)
        assertTrue(ok == false && c.feeRate() == originalFeeRate);
    }
}

