    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initialize with a feeRate of 5000
        c.initialize(address(0), address(0), 1e18, 1e18, 0, 5000, bytes32(0), false, false);

        // As a non-owner (address(1)), try to call setFeeRate
        vm.prank(address(1));
        // In the reference, this reverts due to onlyOwner. In the buggy version, it succeeds.
        // We wrap in try/catch to avoid the revert in reference
        bool setSucceeded;
        try c.setFeeRate(1000) {
            setSucceeded = true;
        } catch {
            setSucceeded = false;
        }

        // The setFeeRate is the only way the difference manifests
        // Now call availableForFlashLoan (any call that doesn't change state)
        // This does not affect feeRate, but we need an external call to complete the scenario
        // We just read feeRate directly
        uint256 feeRateAfter = c.feeRate();

        // If the buggy version succeeded (non-owner could change), feeRate would be 1000
        // If the reference version caught revert, feeRate remains 5000
        assertTrue(feeRateAfter == 5000);
    }
}

