pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // 1. Deploy with no initialization yet; call initialize (sets state)
        // Use dummy addresses for baseToken, nft, etc.
        address dummy = address(0xdead);
        c.initialize(
            dummy,              // _baseToken
            dummy,              // _nft
            1000 ether,          // _virtualBaseTokenReserves
            100,                 // _virtualNftReserves
            0,                   // _changeFee
            500,                 // _feeRate
            bytes32(0),          // _merkleRoot
            false,               // _useStolenNftOracle
            false                // _payRoyalties
        );

        // 2. Call availableForFlashLoan on a token that does not exist (will revert internally)
        // This call does not revert externally; just triggers the function.
        // After this call, the state variable initialized is accessed inside the view.
        // But we want to observe initialized AFTER the call. The getter is c.initialized().
        // The reference: initialized = true (set in initialize).
        // The bug: initialized = false (set in initialize).
        // So we assert that c.initialized() is true (reference) vs false (bug).
        // However the property says the difference is after a call to availableForFlashLoan.
        // So we call it, then check the getter.
        bool success;
        try c.availableForFlashLoan(address(0x1234), 1) returns (bool) {
            success = true;
        } catch {
            success = false;
        }
        // Now assert that initialized() is true; it fails on bug because bug set it false.
        assertEq(c.initialized(), true);
    }
}

